do $pvp_test_environment$
begin
  if current_setting('server_version_num')::integer / 10000 <> 17 then
    raise exception 'PvP runtime tests require PostgreSQL 17';
  end if;

  if (select count(*) from pg_roles
      where rolname in ('anon', 'authenticated', 'service_role')) <> 3 then
    raise exception 'Supabase API roles are missing';
  end if;

  if to_regclass('auth.users') is null then
    raise exception 'Supabase Auth table auth.users is missing';
  end if;

  if to_regclass('realtime.messages') is null then
    raise exception 'Local Supabase Realtime schema is missing';
  end if;

  if not exists (
    select 1 from pg_publication where pubname = 'supabase_realtime'
  ) then
    raise exception 'Local Supabase Realtime publication is missing';
  end if;
end
$pvp_test_environment$;

create extension if not exists pgtap with schema extensions;


-- Minimal player profile fixture for server-authoritative RPG PvP migrations.
create table if not exists public.players (
  id bigint generated by default as identity primary key,
  user_id uuid unique references auth.users(id) on delete set null,
  username text unique,
  rpg_upgrades jsonb not null default '{}'::jsonb,
  inventory jsonb not null default '[]'::jsonb,
  item_points integer not null default 0
);

create table if not exists public.realtime_room_access (
  topic text primary key,
  room_kind text not null,
  host_user_id uuid references auth.users(id) on delete set null,
  guest_user_id uuid references auth.users(id) on delete set null,
  invitee_user_id uuid references auth.users(id) on delete set null,
  is_public boolean not null default false,
  expires_at timestamptz not null
);

alter table public.realtime_room_access enable row level security;
revoke all privileges on table public.realtime_room_access from public, anon, authenticated, service_role;
